package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.webkit.*;
/** Offline surface/lifecycle checks; does not claim successful YouTube streaming. */
public class PanelFullscreenChecks extends Instrumentation {
 LauncherActivity a;DashWebPlayer player;int checks;
 View find(View v,String desc){if(desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){View hit=find(group.getChildAt(i),desc);if(hit!=null)return hit;}}return null;}
 void check(boolean v,String why){if(!v)throw new AssertionError(why);checks++;}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  java.util.concurrent.CountDownLatch catalog=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(catalog::countDown));check(catalog.await(45,java.util.concurrent.TimeUnit.SECONDS),"initial catalog ready before mounting fixture");waitForIdleSync();
  ui(()->{player=new DashWebPlayer(a,640,360);a.body.removeAllViews();a.body.addView(player,new android.widget.LinearLayout.LayoutParams(-1,-1));player.resume();check(player.ensureWeb()!=null,"offline WebView available");});
  ui(()->{View stage=(View)player.web.getParent();check(player.web.getMeasuredWidth()==a.dp(640)&&player.web.getMeasuredHeight()==a.dp(360),"browser measures the complete virtual layout");check(stage.getWidth()>=player.web.getWidth()*player.web.getScaleX()-1,"scaled browser fits panel width");check(stage.getHeight()>=player.web.getHeight()*player.web.getScaleY()-1,"scaled browser fits panel height");});
  int[] hidden={0};WebChromeClient.CustomViewCallback callback=()->hidden[0]++;View[] video={null};int[] flags={0},systemUi={0};
  ui(()->{flags[0]=a.getWindow().getAttributes().flags;systemUi[0]=a.getWindow().getDecorView().getSystemUiVisibility();video[0]=new android.widget.FrameLayout(a);player.showFullscreen(video[0],callback);check(player.isFullscreen(),"custom video active");check(player.getChildAt(player.getChildCount()-1).getVisibility()==View.GONE,"browser toolbar hidden during fullscreen");check(video[0].getParent().getParent().getParent()==player.body,"video belongs to panel body");});
  ui(()->{View overlay=(View)video[0].getParent().getParent();check(overlay.getWidth()==player.body.getWidth()&&overlay.getHeight()==player.body.getHeight(),"video overlay fills panel");check(video[0].getHeight()==player.body.getHeight(),"video uses full height with controls overlaid");View sizing=find(overlay,"Toggle fit or fill video; fill crops edges");check(sizing!=null,"fit/fill control available");View host=(View)video[0].getParent();check(((android.widget.TextView)sizing).getText().toString().startsWith("Isi"),"crop is the fullscreen default");check(Math.abs(host.getScaleX()-DashWebPlayer.fillScale(host.getWidth(),host.getHeight(),16f/9f))<.001f&&host.getScaleX()==host.getScaleY(),"default crop applies uniform fill geometry");sizing.performClick();check(host.getScaleX()==1&&host.getScaleY()==1,"Muat reverses crop");sizing.performClick();check(host.getScaleX()>=1&&host.getScaleX()==host.getScaleY(),"Isi restores uniform crop");player.expandFullscreen();check(video[0].getParent().getParent().getParent()==a.getWindow().getDecorView(),"explicit expansion uses Activity");check(player.exitFullscreen(),"exit handled");check(player.getChildAt(player.getChildCount()-1).getVisibility()==View.VISIBLE,"browser toolbar restored after fullscreen");check(hidden[0]==1,"provider callback once");check(video[0].getParent()==null,"surface detached");check(a.getWindow().getAttributes().flags==flags[0],"window flags restored");check(a.getWindow().getDecorView().getSystemUiVisibility()==systemUi[0],"system UI restored");check(!player.exitFullscreen()&&hidden[0]==1,"exit idempotent");});
  ui(()->{player.showFullscreen(new android.widget.FrameLayout(a),callback);player.pause();check(!player.isFullscreen()&&player.web==null,"pause releases surface and WebView");check(hidden[0]==2,"pause notifies provider");});
  out.putString("stream","PASS: "+checks+" panel fullscreen assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+checks+": "+t+"\n");}finally{if(a!=null)ui(()->{if(player!=null)player.close();a.finish();});}finish(code,out);}
}
